'use client'

import Image from 'next/image'
import { useId, useState, type ReactNode } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { ArrowUpRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type InteractiveFeature = {
  id: string
  title: string
  description: string
  eyebrow?: string
  icon?: ReactNode
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type InteractiveFeatureShowcaseProps = {
  title?: string
  description?: string
  features: InteractiveFeature[]
  defaultValue?: string
  className?: string
}

export function InteractiveFeatureShowcase({
  title,
  description,
  features,
  defaultValue,
  className,
}: InteractiveFeatureShowcaseProps) {
  const generatedId = useId()
  const reduceMotion = useReducedMotion()
  const [activeId, setActiveId] = useState(defaultValue ?? features[0]?.id)
  const active = features.find((feature) => feature.id === activeId) ?? features[0]

  if (!active) return null

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        {(title || description) && (
          <div className="mb-10 max-w-2xl">
            {title ? (
              <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
            ) : null}
          </div>
        )}
        <div className="grid overflow-hidden rounded-3xl border bg-card shadow-xl shadow-black/5 lg:grid-cols-[0.8fr_1.2fr]">
          <div role="tablist" aria-label={title ?? 'Recursos'} className="flex flex-col p-3 md:p-5">
            {features.map((feature, index) => {
              const selected = feature.id === active.id
              return (
                <button
                  type="button"
                  role="tab"
                  id={`${generatedId}-tab-${feature.id}`}
                  aria-controls={`${generatedId}-panel-${feature.id}`}
                  aria-selected={selected}
                  onClick={() => setActiveId(feature.id)}
                  className={cn(
                    'group relative flex w-full gap-4 rounded-2xl p-4 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                    selected ? 'bg-primary text-primary-foreground' : 'hover:bg-muted',
                  )}
                  key={feature.id}
                >
                  <span
                    className={cn(
                      'flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border text-sm font-bold',
                      selected
                        ? 'border-white/15 bg-white/10'
                        : 'bg-background text-muted-foreground',
                    )}
                  >
                    {feature.icon ?? String(index + 1).padStart(2, '0')}
                  </span>
                  <span className="min-w-0">
                    {feature.eyebrow ? (
                      <span
                        className={cn(
                          'block text-[10px] font-bold uppercase tracking-[0.16em]',
                          selected ? 'text-primary-foreground/70' : 'text-primary',
                        )}
                      >
                        {feature.eyebrow}
                      </span>
                    ) : null}
                    <span className="mt-1 block font-semibold">{feature.title}</span>
                    <span
                      className={cn(
                        'mt-1 line-clamp-2 block text-sm',
                        selected ? 'text-primary-foreground/80' : 'text-muted-foreground',
                      )}
                    >
                      {feature.description}
                    </span>
                  </span>
                  {selected ? (
                    <motion.span
                      layoutId={`${generatedId}-indicator`}
                      className="absolute inset-y-4 left-0 w-1 rounded-r-full bg-primary-foreground"
                    />
                  ) : null}
                </button>
              )
            })}
          </div>

          <div
            role="tabpanel"
            id={`${generatedId}-panel-${active.id}`}
            aria-labelledby={`${generatedId}-tab-${active.id}`}
            className="relative min-h-[420px] overflow-hidden bg-muted"
          >
            <AnimatePresence mode="wait" initial={false}>
              <motion.div
                key={active.id}
                className="absolute inset-0"
                initial={reduceMotion ? false : { opacity: 0, scale: 1.03 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={reduceMotion ? undefined : { opacity: 0, scale: 0.98 }}
                transition={{ duration: reduceMotion ? 0 : 0.4 }}
              >
                <Image
                  src={active.image.src}
                  alt={active.image.alt}
                  fill
                  className="object-cover"
                  sizes="(min-width: 1024px) 60vw, 100vw"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent" />
                <div className="absolute inset-x-0 bottom-0 p-6 text-white md:p-8">
                  <p className="max-w-xl text-lg leading-7 text-white/75">{active.description}</p>
                  {active.action ? (
                    <a
                      href={active.action.href}
                      className="mt-5 inline-flex items-center gap-2 rounded-lg bg-white px-4 py-2 text-sm font-semibold text-slate-950 transition hover:bg-white/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
                    >
                      {active.action.label}
                      <ArrowUpRight className="h-4 w-4" />
                    </a>
                  ) : null}
                </div>
              </motion.div>
            </AnimatePresence>
          </div>
        </div>
      </div>
    </section>
  )
}

import Link from 'next/link'
import { Check } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type PricingCardsProps = {
  title?: string
  plans: Array<{
    name: string
    price: string
    period?: string
    description?: string
    features: string[]
    action: { label: string; href: string }
    highlighted?: boolean
  }>
  className?: string
}

export function PricingCards({ title, plans, className }: PricingCardsProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'pricing-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2
            id="pricing-title"
            className="mb-12 text-center text-3xl font-bold tracking-tight md:text-4xl"
          >
            {title}
          </h2>
        ) : null}
        <div className="mx-auto grid max-w-6xl items-stretch gap-6 lg:grid-cols-3">
          {plans.map((plan) => (
            <article
              key={plan.name}
              className={cn(
                'flex flex-col rounded-2xl border bg-card p-7 shadow-sm',
                plan.highlighted && 'border-primary ring-2 ring-primary/20',
              )}
            >
              {plan.highlighted ? (
                <span className="mb-4 w-fit rounded-full bg-primary px-3 py-1 text-xs font-semibold text-primary-foreground">
                  Mais escolhido
                </span>
              ) : null}
              <h3 className="text-xl font-semibold">{plan.name}</h3>
              {plan.description ? (
                <p className="mt-2 text-sm text-muted-foreground">{plan.description}</p>
              ) : null}
              <p className="mt-6">
                <span className="text-4xl font-bold">{plan.price}</span>
                {plan.period ? <span className="text-muted-foreground">/{plan.period}</span> : null}
              </p>
              <ul className="my-7 flex-1 space-y-3">
                {plan.features.map((feature) => (
                  <li key={feature} className="flex gap-3 text-sm">
                    <Check className="h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                    {feature}
                  </li>
                ))}
              </ul>
              <Button asChild variant={plan.highlighted ? 'default' : 'outline'}>
                <Link href={plan.action.href}>{plan.action.label}</Link>
              </Button>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState } from 'react'
import { ArrowUpRight, Check } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ProductFeatureTab = {
  id: string
  label: string
  title: string
  description: string
  features?: string[]
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type ProductFeatureTabsProps = {
  eyebrow?: string
  title: string
  items: ProductFeatureTab[]
  initialId?: string
  className?: string
}

export function ProductFeatureTabs({
  eyebrow = 'Soluções',
  title,
  items,
  initialId,
  className,
}: ProductFeatureTabsProps) {
  const instanceId = useId()
  const [activeId, setActiveId] = useState(initialId ?? items[0]?.id)
  const activeItem = items.find((item) => item.id === activeId) ?? items[0]

  if (!activeItem) return null

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <header className="mb-9 max-w-3xl">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
            {eyebrow}
          </p>
          <h2 className="mt-3 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
            {title}
          </h2>
        </header>

        <div
          className="mb-6 flex gap-2 overflow-x-auto pb-2 [scrollbar-width:none] max-sm:flex-wrap [&::-webkit-scrollbar]:hidden"
          role="tablist"
          aria-label={title}
        >
          {items.map((item) => {
            const selected = item.id === activeItem.id
            return (
              <button
                key={item.id}
                id={`${instanceId}-tab-${item.id}`}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-controls={`${instanceId}-panel-${item.id}`}
                tabIndex={selected ? 0 : -1}
                onClick={() => setActiveId(item.id)}
                className={cn(
                  'shrink-0 rounded-full border px-4 py-2 text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  selected
                    ? 'border-primary bg-primary text-primary-foreground'
                    : 'bg-background text-muted-foreground hover:text-foreground',
                )}
              >
                {item.label}
              </button>
            )
          })}
        </div>

        <div
          id={`${instanceId}-panel-${activeItem.id}`}
          role="tabpanel"
          aria-labelledby={`${instanceId}-tab-${activeItem.id}`}
          className="grid overflow-hidden rounded-[2rem] border bg-card shadow-sm lg:grid-cols-2"
        >
          <div className="flex flex-col justify-center p-7 md:p-10 lg:p-12">
            <h3 className="text-2xl font-semibold md:text-3xl">{activeItem.title}</h3>
            <p className="mt-4 leading-7 text-muted-foreground">{activeItem.description}</p>
            {activeItem.features?.length ? (
              <ul className="mt-7 grid gap-3">
                {activeItem.features.map((feature) => (
                  <li key={feature} className="flex gap-3 text-sm">
                    <span className="mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary">
                      <Check className="size-3.5" aria-hidden="true" />
                    </span>
                    {feature}
                  </li>
                ))}
              </ul>
            ) : null}
            {activeItem.action ? (
              <a
                href={activeItem.action.href}
                className="mt-8 inline-flex w-fit items-center gap-2 font-semibold text-primary hover:underline"
              >
                {activeItem.action.label}
                <ArrowUpRight className="size-4" aria-hidden="true" />
              </a>
            ) : null}
          </div>
          <div className="relative min-h-72 overflow-hidden bg-muted lg:min-h-[480px]">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              key={activeItem.id}
              src={activeItem.image.src}
              alt={activeItem.image.alt}
              className="size-full object-cover motion-safe:duration-500 motion-safe:animate-in motion-safe:fade-in"
            />
          </div>
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type CTABannerProps = {
  title: string
  description?: string
  primaryAction: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  backgroundImage?: { src: string; alt?: string }
  className?: string
}

export function CTABanner({
  title,
  description,
  primaryAction,
  secondaryAction,
  backgroundImage,
  className,
}: CTABannerProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-primary py-16 text-primary-foreground md:py-20',
        className,
      )}
      aria-labelledby="cta-banner-title"
    >
      {backgroundImage ? (
        <Image
          src={backgroundImage.src}
          alt={backgroundImage.alt ?? ''}
          fill
          className="-z-20 object-cover opacity-25"
          sizes="100vw"
        />
      ) : null}
      {backgroundImage ? <div className="absolute inset-0 -z-10 bg-primary/80" /> : null}
      <div className="container text-center">
        <h2
          id="cta-banner-title"
          className="mx-auto max-w-3xl text-3xl font-bold tracking-tight md:text-5xl"
        >
          {title}
        </h2>
        {description ? (
          <p className="mx-auto mt-5 max-w-2xl text-lg opacity-85">{description}</p>
        ) : null}
        <div className="mt-8 flex flex-wrap justify-center gap-3">
          <Button asChild size="lg" variant="secondary">
            <Link href={primaryAction.href}>{primaryAction.label}</Link>
          </Button>
          {secondaryAction ? (
            <Button
              asChild
              size="lg"
              variant="outline"
              className="border-current bg-transparent text-current hover:bg-white/10 hover:text-current"
            >
              <Link href={secondaryAction.href}>{secondaryAction.label}</Link>
            </Button>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId } from 'react'
import { HelpCircle } from 'lucide-react'

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion'
import { cn } from '@/lib/utils'

export type FAQCenteredProps = {
  eyebrow?: string
  title: string
  description?: string
  items: Array<{
    question: string
    answer: React.ReactNode
  }>
  className?: string
}

export function FAQCentered({
  eyebrow = 'Central de ajuda',
  title,
  description,
  items,
  className,
}: FAQCenteredProps) {
  const titleId = useId()

  return (
    <section className={cn('py-16 md:py-24', className)} aria-labelledby={titleId}>
      <div className="container">
        <header className="mx-auto mb-10 max-w-2xl text-center">
          <span className="mb-5 inline-flex items-center gap-2 rounded-full border bg-background px-3 py-1 text-xs font-semibold uppercase tracking-wider text-muted-foreground shadow-sm">
            <HelpCircle className="size-3.5 text-primary" aria-hidden="true" />
            {eyebrow}
          </span>
          <h2 id={titleId} className="text-balance text-3xl font-bold tracking-tight md:text-5xl">
            {title}
          </h2>
          {description ? (
            <p className="mx-auto mt-4 max-w-xl text-balance text-muted-foreground">
              {description}
            </p>
          ) : null}
        </header>

        <Accordion type="single" collapsible className="mx-auto max-w-3xl space-y-3">
          {items.map((item, index) => (
            <AccordionItem
              key={item.question}
              value={`faq-centered-${index}`}
              className="rounded-2xl border bg-card px-5 shadow-sm data-[state=open]:border-primary/30 data-[state=open]:shadow-md"
            >
              <AccordionTrigger className="py-5 text-left text-base font-semibold hover:no-underline">
                {item.question}
              </AccordionTrigger>
              <AccordionContent className="pb-5 pr-8 leading-7 text-muted-foreground">
                {item.answer}
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroSplitProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  action?: { label: string; href: string }
  imagePosition?: 'left' | 'right'
  className?: string
}

export function HeroSplit({
  title,
  description,
  image,
  eyebrow,
  action,
  imagePosition = 'right',
  className,
}: HeroSplitProps) {
  return (
    <section
      className={cn('overflow-hidden border-b bg-background', className)}
      aria-labelledby="hero-split-title"
    >
      <div className="container grid min-h-[520px] items-center gap-10 py-12 lg:grid-cols-2 lg:py-20">
        <div className={cn('max-w-xl', imagePosition === 'left' && 'lg:order-2')}>
          {eyebrow ? (
            <p className="mb-3 text-sm font-semibold uppercase tracking-widest text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h1 id="hero-split-title" className="text-4xl font-bold tracking-tight sm:text-5xl">
            {title}
          </h1>
          {description ? (
            <p className="mt-5 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
          {action ? (
            <Button asChild className="mt-8" size="lg">
              <Link href={action.href}>{action.label}</Link>
            </Button>
          ) : null}
        </div>
        <div
          className={cn(
            'relative aspect-[4/3] overflow-hidden rounded-3xl bg-muted shadow-xl',
            imagePosition === 'left' && 'lg:order-1',
          )}
        >
          <Image
            src={image.src}
            alt={image.alt}
            fill
            priority
            className="object-cover"
            sizes="(min-width: 1024px) 50vw, 100vw"
          />
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
      src={BLOOMIN_LOGO_SRC}
      alt="Bloomin"
      width={Math.round(height * (421 / 108))}
      height={height}
      className={cn('h-[1.125rem] w-auto', className)}
      style={{ height, width: 'auto' }}
    />
  )
}

export type BloominCreditProps = {
  label?: string
  href?: string
  className?: string
  /** Fundo escuro atrás do logo (o PNG oficial tem fundo preto). */
  logoClassName?: string
}

/** Crédito padrão “Desenvolvido por” com o logo da Bloomin. */
export function BloominCredit({
  label = 'Desenvolvido por',
  href = BLOOMIN_URL,
  className,
  logoClassName,
}: BloominCreditProps) {
  return (
    <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
      <span className="opacity-80">{label}</span>
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Bloomin — agência de marketing digital"
        className={cn(
          'inline-flex items-center rounded-md bg-neutral-950 px-2 py-1 transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          logoClassName,
        )}
      >
        <BloominLogo height={16} />
      </a>
    </span>
  )
}

import * as React from 'react'

import { CurrentYear } from '@/components/library/primitives/CurrentYear'
import { cn } from '@/lib/utils'

import { BloominCredit } from './BloominCredit'
import type { FooterColumn, NavigationBrand, NavigationLink, SocialLink } from './types'

export interface FooterColumnsProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  brand: NavigationBrand
  description?: React.ReactNode
  columns: readonly FooterColumn[]
  socialLinks?: readonly SocialLink[]
  legalLinks?: readonly NavigationLink[]
  copyright?: React.ReactNode
  navigationLabel?: string
  hideBrandLabel?: boolean
  /** Exibe “Desenvolvido por” com o logo da Bloomin. Padrão: true. */
  showDevelopedBy?: boolean
}

export function FooterColumns({
  brand,
  description,
  columns,
  socialLinks = [],
  legalLinks = [],
  copyright,
  navigationLabel = 'Navegação do rodapé',
  hideBrandLabel = false,
  showDevelopedBy = true,
  className,
  ...props
}: FooterColumnsProps) {
  const columnGrid =
    columns.length >= 4
      ? 'lg:grid-cols-4'
      : columns.length === 3
        ? 'lg:grid-cols-3'
        : columns.length === 2
          ? 'lg:grid-cols-2'
          : 'lg:grid-cols-1'

  return (
    <footer className={cn('border-t bg-muted/30', className)} {...props}>
      <div className="mx-auto grid max-w-7xl gap-10 px-4 py-12 sm:px-6 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,2fr)] lg:px-8 lg:py-16">
        <div>
          <a
            href={brand.href ?? '/'}
            className="inline-flex items-center gap-3 rounded-sm font-semibold tracking-tight focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {brand.logo}
            <span className={cn(hideBrandLabel && brand.logo && 'sr-only')}>{brand.label}</span>
          </a>
          {description ? (
            <div className="mt-4 max-w-sm text-sm leading-6 text-muted-foreground">
              {description}
            </div>
          ) : null}
          {socialLinks.length ? (
            <ul className="mt-6 flex flex-wrap gap-2" aria-label="Redes sociais">
              {socialLinks.map((link) => (
                <li key={link.href}>
                  <a
                    href={link.href}
                    aria-label={link.label}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex h-10 w-10 items-center justify-center rounded-full border text-muted-foreground transition-colors hover:border-primary hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {link.icon}
                  </a>
                </li>
              ))}
            </ul>
          ) : null}
        </div>

        <nav className={cn('grid gap-8 sm:grid-cols-2', columnGrid)} aria-label={navigationLabel}>
          {columns.map((column) => (
            <div key={column.title}>
              <h2 className="text-sm font-semibold">{column.title}</h2>
              <ul className="mt-4 space-y-3">
                {column.links.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      target={link.external ? '_blank' : undefined}
                      rel={link.external ? 'noopener noreferrer' : undefined}
                      aria-current={link.current ? 'page' : undefined}
                      className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </nav>
      </div>

      <div className="border-t">
        <div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-6 text-sm text-muted-foreground sm:px-6 md:flex-row md:items-center md:justify-between lg:px-8">
          <div>
            {copyright ?? (
              <>
                © <CurrentYear /> {brand.label}
              </>
            )}
          </div>
          <div className="flex flex-wrap items-center gap-x-5 gap-y-2">
            {legalLinks.length ? (
              <ul className="flex flex-wrap gap-x-5 gap-y-2">
                {legalLinks.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      target={link.external ? '_blank' : undefined}
                      rel={link.external ? 'noopener noreferrer' : undefined}
                      className="transition-colors hover:text-foreground focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            ) : null}
            {showDevelopedBy ? <BloominCredit /> : null}
          </div>
        </div>
      </div>
    </footer>
  )
}

